/* WARNING: Script requires that SQLITE_DBCONFIG_DEFENSIVE be disabled */
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE mailbox (
    account TEXT NOT NULL,
    name TEXT NOT NULL,
    -- Its special use (RFC 6154), as `Role::label` names it; NULL for none.
    role TEXT,
    uid_validity INTEGER,
    uid_next INTEGER,
    highest_modseq INTEGER,
    -- The server's `EXISTS` as the last resync or IDLE update saw it.
    exists_count INTEGER,
    -- NULL until a resync or a `STATUS` counts it.
    unread INTEGER,
    PRIMARY KEY (account, name)
);
INSERT INTO mailbox VALUES('me@example.com','INBOX',NULL,1,104,4,3,0);
CREATE TABLE message (
    account TEXT NOT NULL,
    mailbox TEXT NOT NULL,
    uid INTEGER NOT NULL,
    -- The `body` row of this Message, once fetched: see docs/adr/0005-body-cache-key.md.
    body_key INTEGER NOT NULL,
    received INTEGER NOT NULL,
    received_offset INTEGER NOT NULL,
    unread INTEGER NOT NULL,
    answered INTEGER NOT NULL,
    sender TEXT NOT NULL,
    from_line TEXT NOT NULL,
    to_line TEXT NOT NULL,
    subject TEXT NOT NULL,
    -- Gmail's `X-GM-THRID`; NULL on another server.
    thread INTEGER,
    -- Elsewhere, the Thread by `References`, as `RootId` hashes it; NULL on
    -- Gmail: docs/adr/0009-threads-from-gmail-thread-id.md.
    root INTEGER,
    from_me INTEGER NOT NULL,
    -- NULL until the second fetch phase writes it.
    snippet TEXT,
    -- The part the Snippet and the Preview show; NULL with no text part.
    text_section TEXT,
    text_encoding TEXT,
    text_charset TEXT,
    text_html INTEGER,
    -- One `size\tname` line per attachment; empty with none.
    attachments TEXT NOT NULL,
    PRIMARY KEY (account, mailbox, uid)
);
INSERT INTO message VALUES('me@example.com','INBOX',101,1800000000000000001,1709283600,0,0,0,'Alice','Alice <someone@example.com>','','Oldest',1800000000000000001,NULL,0,'Body of Oldest','1','identity','utf-8',0,'');
INSERT INTO message VALUES('me@example.com','INBOX',102,1800000000000000002,1709370000,0,0,0,'Bob','Bob <someone@example.com>','','Middle',1800000000000000002,NULL,0,'Body of Middle','1','identity','utf-8',0,'');
PRAGMA writable_schema=ON;
